// IfTableWatcher is a table-aware Watcher over IfTable.
// The zero value is not usable; construct via IfTable.Watch(ctx, sess, cols, opts...).
// Use a single iterator. The other methods may be called concurrently.
type IfTableWatcher struct {
	w *snmp.Watcher[IfTableRow]
}

// Iter returns the range-over-func view of the Watcher's event stream.
// See [snmp.Watcher.Iter] for the contract.
func (tw *IfTableWatcher) Iter() iter.Seq2[snmp.OID, snmp.WatchEvent[IfTableRow]] {
	return tw.w.Iter()
}

// Err returns the underlying Watcher's terminal error, or nil if it
// completed naturally. See [snmp.Watcher.Err].
func (tw *IfTableWatcher) Err() error {
	return tw.w.Err()
}

// Close signals the Watcher's tick goroutine to terminate. Idempotent.
// See [snmp.Watcher.Close].
func (tw *IfTableWatcher) Close() error {
	return tw.w.Close()
}

// Fallback reports whether the Watcher has transitioned to fallback
// mode. See [snmp.Watcher.Fallback].
func (tw *IfTableWatcher) Fallback() bool {
	return tw.w.Fallback()
}

// LastTickErr returns the most-recent transient per-tick error.
// See [snmp.Watcher.LastTickErr].
func (tw *IfTableWatcher) LastTickErr() error {
	return tw.w.LastTickErr()
}

// TableRoot returns the OID of the table this Watcher operates over.
func (tw *IfTableWatcher) TableRoot() snmp.OID {
	return tw.w.TableRoot()
}

// Watch opens a long-lived watch on IfTable.
//
// cols selects the columns whose values are reported on every emitted
// event. opts override cadence bounds, per-column tier classifications,
// fallback behavior, and other policy — see [snmp.WatchOption] for the
// full set.
//
// cols is a slice rather than variadic because opts is variadic and
// Go forbids two variadic parameters.
//
// Events emitted on this stream:
//   - ChangeKindAdded    — Row populated, Prev always nil.
//   - ChangeKindModified — Row is current state. Prev is nil unless
//     the caller passed [snmp.WithPrevRow]; when
//     set, Prev carries the previous Row.
//   - ChangeKindRemoved  — Row carries the last-known state at the
//     time the row disappeared. Prev is nil.
//
// The returned Watcher must be Closed when the caller is done; iteration
// exit alone does not free the underlying goroutine until Close.
//
// On validation failure (invalid cadence bounds, tier override of the
// indicator column, etc.) Watch returns a Watcher whose Err() returns
// the cause immediately; range loops exit without emitting events and
// Close is a no-op.
func (ifTableT) Watch(ctx context.Context, sess snmp.Session, cols []snmp.AnyColumn, opts ...snmp.WatchOption) *IfTableWatcher {
	allOpts := append([]snmp.WatchOption{snmp.WithTierLookup(ColumnTier)}, opts...)
	w, _ := snmp.NewWatcher[IfTableRow](ctx, sess, IfTableIndicator, cols, decodeIfTableRow, equalIfTableRow, mergeIfTableRow, allOpts...)

	return &IfTableWatcher{w: w}
}

// IfName is ifName.
// The textual name of the interface. The value of this object should be
// the name of the interface as assigned by the local device and should be
// suitable for use in commands entered at the device's `console'. This
// might be a text name, such as `le0' or a simple port number, such as
// `1', depending on the interface naming syntax of the device. If several
// entries in the ifTable together represent a single interface as named by
// the device, then each will have the same value of ifName. Note that for
// an agent which responds to SNMP queries concerning an interface on some
// other (proxied) device, then the value of ifName for such an interface
// is the proxied device's local name for it. If there is no local name, or
// this object is otherwise not applicable, then this object contains a
// zero-length string.
var IfName = snmp.NewTableColumn[string](snmp.MustOID(1, 3, 6, 1, 2, 1, 31, 1, 1, 1, 1), snmp.KindOctetString, snmp.DecodeDisplayString, 0)

// IfInMulticastPkts is ifInMulticastPkts.
// The number of packets, delivered by this sub-layer to a higher
// (sub-)layer, which were addressed to a multicast address at this
// sub-layer. For a MAC layer protocol, this includes both Group and
// Functional addresses. Discontinuities in the value of this counter can
// occur at re-initialization of the management system, and at other times
// as indicated by the value of ifCounterDiscontinuityTime.
var IfInMulticastPkts = snmp.NewFusedTableColumn[uint32](snmp.MustOID(1, 3, 6, 1, 2, 1, 31, 1, 1, 1, 2), snmp.KindCounter32, snmp.DecodeUint32, snmp.RawCounter32, 1)

// IfInBroadcastPkts is ifInBroadcastPkts.
