// decodeIfStackTableRow decodes one row of IfStackTable from the supplied
// VarBinds. Each VarBind's OID determines which row field it populates
// (via the column's last sub-id). VarBinds with unknown column-ids are
// ignored. Absent columns leave their field at its zero value.
func decodeIfStackTableRow(idx snmp.OID, vbs []snmp.VarBind) (IfStackTableRow, error) {
	var row IfStackTableRow
	row.Key, row.keyValid = decodeIfStackTableKey(idx)

	for _, vb := range vbs {
		o := vb.GetHeader().OID
		if o.Len() == 0 {
			continue
		}
		entryLen := snmp.MustOID(1, 3, 6, 1, 2, 1, 31, 1, 2, 1).Len()
		if o.Len() <= entryLen {
			continue
		}
		colID := o.At(entryLen)
		if colID == 3 {
			dv, derr := IfStackStatus.Decode(vb)
			if derr != nil {
				return row, derr
			}
			row.IfStackStatus = dv
			row.observed[0] |= 1 << 0
		}
	}

	return row, nil
}

// equalIfStackTableRow compares two IfStackTableRow values for equality.
// Used by [snmp.Watcher] to compute ChangeKindModified emits. Field-by-
// field with the type-appropriate comparator (bytes.Equal for []byte,
// OID.Equal for OID, time.Time.Equal for time.Time, == for everything else).
func equalIfStackTableRow(a IfStackTableRow, b IfStackTableRow) bool {
	return a.Key == b.Key && a.keyValid == b.keyValid && a.observed == b.observed && a.IfStackStatus == b.IfStackStatus
}

// mergeIfStackTableRow merges the values decoded from vbs into dst, leaving fields
// whose columns are not present in vbs unchanged. Used by [snmp.Watcher]
// to maintain per-row state under partial-column fetches (Counter-tier,
// Static-tier). Best-effort: individual VarBind decode failures are
// silently skipped rather than propagated, because partial-fetch ticks
// surface transient errors through [snmp.Watcher.LastTickErr] at the
// call-site granularity rather than per-VarBind.
func mergeIfStackTableRow(dst *IfStackTableRow, vbs []snmp.VarBind) {
	for _, vb := range vbs {
		o := vb.GetHeader().OID
		if o.Len() == 0 {
			continue
		}
		entryLen := snmp.MustOID(1, 3, 6, 1, 2, 1, 31, 1, 2, 1).Len()
		if o.Len() <= entryLen {
			continue
		}
		colID := o.At(entryLen)
		if colID == 3 {
			dv, derr := IfStackStatus.Decode(vb)
			if derr == nil {
				dst.IfStackStatus = dv
				dst.observed[0] |= 1 << 0
			}
		}
	}
}

